# coding: utf-8
from lesson_authoring import entry as E
B=[['希腊 teinein → tonos','拉伸 → 张紧、琴弦张力；音调'],['拉丁 tonus → 古法语 ton → 英语 tone','声音、音调 → 语气等']]
U=B+[['中古英语 tone／tune 两种形式','同族变体；元音变化的具体原因不明'],['英语 tune','曲调；调准音高或设备']]
W=[
E('tone','英 /təʊn/；美 /toʊn/','音调、音色；语气、基调；色调；肌肉张力','弦拉得怎样，声音就怎样；声音带着怎样的感觉，又变成语气和基调。','经法语、拉丁语接希腊 tonos，原有拉紧、张力的含义；与 teinein“拉伸”相关。',B,'That tone of voice 是那种说话口气，不只是音高；the tone of an email 是文字透露的态度。颜色的 tone 是色调，muscle tone 是肌肉张力。它们沿“张力、声音特性、整体感觉”等支线展开，不能把每个义项都硬说成声波。','tone of voice；set the tone；a warm tone；tone down。','pitch 更明确指音高，tone 可以包括音色或语气。tone down 是把颜色、措辞或强度缓和，不只是把声音调低。',('Her tone was calm, but the message was firm.','她的语气很平静，但意思很坚定。'),('The opening paragraph sets the tone for the whole report.','开头一段为整份报告定下了基调。'),('Could you tone down the wording a little?','你能把措辞稍微缓和一点吗？'),sources=['https://www.etymonline.com/word/tone','https://en.wiktionary.org/wiki/tone']),
E('tune','英 /tjuːn/；美 /tuːn/','曲调；调音；调谐、调整','把声音调到合适的位置，再把一串音连成可辨认的曲调。','与 tone 是中古英语中的同族形式，具体元音变化原因不明；动词由曲调、合适音高的名词用法发展。',U,'hum a tune 是哼一段旋律，tune a guitar 是给吉他调音。后来 tune 扩展到调整发动机、无线电和软件参数，让它们进入合适状态；in tune with someone 则比喻与某人的想法合拍。','a catchy tune；tune a guitar；in tune；out of tune；tune in to。','tone 常说一个声音的性质或说话态度，tune 通常是一段可辨认的曲调。调音 tune 与开大音量 turn up 不是同一回事。',('I recognise the tune, but I cannot remember the words.','我认得这段旋律，却记不起歌词。'),('She tuned the guitar before the performance.','她在演出前给吉他调了音。'),sources=['https://www.etymonline.com/word/tune','https://en.wiktionary.org/wiki/tune']),
E('tuning','英 /ˈtjuːnɪŋ/；美 /ˈtuːnɪŋ/','调音、调谐；参数调整','反复转动一点、试听一下，直到系统工作在合适的位置。','tune 去末尾不发音 e 加 -ing；表示调整音高、频率或性能的动作与过程。',U+[['英语 tune → tuning','调准 → 调音、调谐和调整过程']],'piano tuning 是给钢琴调音；performance tuning 是调整程序或设备，让性能更符合需要。它常是通过具体参数改善已有系统，不必从头重建。名词 tuning 也可以指乐器采用的一套定弦方式。','piano tuning；performance tuning；standard tuning；tuning a radio。','tuning 侧重调到合适状态，repair 侧重修复故障。没有坏掉的乐器也可能需要 tuning。',('The piano needs tuning before the concert.','音乐会前，这架钢琴需要调音。'),('Careful tuning improved the system’s response time.','细致的参数调整改善了系统的响应时间。'),sources=['https://en.wiktionary.org/wiki/tuning','https://www.etymonline.com/word/tune']),
E('tuner','英 /ˈtjuːnə/；美 /ˈtuːnər/','调音师；调音器；调谐器','负责把声音或接收频率调准的人或装置。','tune + -er，表示做这件事的人或工具；去词尾 e 后接 -er。',U+[['英语 tune + -er → tuner','调音的人；调谐或调音工具']],'a piano tuner 是钢琴调音师，a guitar tuner 常是一件测量音高、帮助调弦的工具；无线电的 tuner 则负责选择接收频率。同一个 -er 可以指人也可以指设备，具体看前面的搭配。','a piano tuner；an electronic tuner；a radio tuner。','tuner 不一定会自动转动琴弦，有些只显示音高偏差；实际动作由使用者完成。它也不是音量旋钮的通用名称。',('The piano tuner arrived early in the morning.','钢琴调音师一大早就到了。'),('I use a small electronic tuner for my guitar.','我用一个小型电子调音器给吉他调音。'),sources=['https://en.wiktionary.org/wiki/tuner']),
E('tunable','英 /ˈtjuːnəbl/；美 /ˈtuːnəbl/','可调音的；可调谐、可调整的','留了可拧动的空间，能够调到需要的状态。','tune + -able，表示可以被调节；通常写 tunable，另见 tuneable。',U+[['英语 tune + -able → tunable','可以调准音高、频率或参数的']],'a tunable laser 是波长可调的激光器，tunable parameters 是可以调整的参数。这个词表达调整能力，不说明已经调好了，也不保证可调范围无限；要看具体设备或设计。','tunable parameters；a tunable filter；a tunable laser。','tuned 表示调过或处于某种调谐状态，tunable 表示具备调节可能。',('The filter has a tunable frequency range.','这个滤波器的频率范围可以调节。'),('The program exposes several tunable parameters.','这个程序提供了几个可调整的参数。'),sources=['https://en.wiktionary.org/wiki/tunable']),
E('tuneful','英 /ˈtjuːnfəl/；美 /ˈtuːnfəl/','旋律优美的、悦耳的','有一段容易听进去、让人愿意跟着哼的旋律。','tune + -ful，表示具有曲调、富于旋律；现代常带悦耳的评价。',U+[['英语 tune + -ful → tuneful','富于悦耳旋律的']],'a tuneful song 是旋律好听的歌，不是在说音量大、速度快或技术复杂。它也可以形容鸟鸣等有音乐感的声音。评价重点是旋律与听感，而不是演奏者有多少炫技。','a tuneful song；a tuneful melody；tuneful music。','in tune 强调音准合适，tuneful 强调旋律悦耳；不走音不自动等于作品旋律优美。',('The show is full of short, tuneful songs.','这场演出里有许多简短悦耳的歌曲。'),('A tuneful whistle came from the garden.','花园里传来一阵悦耳的口哨声。'),sources=['https://en.wiktionary.org/wiki/tuneful']),
E('toned','英 /təʊnd/；美 /toʊnd/','肌肉紧实的；调过色的；tone 的过去分词','在不同场景里，是身体显得紧实，或颜色、声音已作了调整。','tone + -d，来自 tone 的不同支线；肌肉紧实义与 tone 的张力、身体状态义相关。',B+[['英语 tone → toned','赋予某种状态 → 紧实的、着色的等']],'toned arms 通常形容手臂肌肉看起来紧实；a toned photograph 可以是调过色的照片。若说 toned down the criticism，则是把批评措辞缓和了。先看对象，不能把 toned 到处翻译成“有音调”。','toned muscles；toned arms；a toned photograph；toned down。','toned 是状态或过去分词，tuned 是 tune 的过去分词，常说调准音高或设备；拼写只差一个字母，搭配不同。',('The portrait shows a dancer with toned arms.','画像画的是一位手臂肌肉紧实的舞者。'),('She toned down the criticism in the final version.','她在最终版本里缓和了批评措辞。'),sources=['https://www.etymonline.com/word/toned','https://en.wiktionary.org/wiki/toned']),
E('tonal','英 /ˈtəʊnəl/；美 /ˈtoʊnəl/','音调或色调的；声调的；调性的','把注意力放在声音、色彩的调子，或音乐的调性组织上。','tone + -al，形成相关形容词；音乐、语言学和视觉艺术分别发展出专门搭配。',B+[['英语 tone + -al → tonal','音调、声调、色调或调性相关的']],'a tonal language 用声调区别词义，tonal contrast 在图像里可能是明暗或色调对比；tonal music 则通常围绕一个调性中心组织。共同来源不代表几个领域的“调”能完全互换。','a tonal language；tonal contrast；tonal balance；tonal music。','tunable 是可调节的，tonal 是与调子有关的。tonal language 不是说这种语言听起来格外悦耳。',('Mandarin is a tonal language.','普通话是一种声调语言。'),('The photograph has subtle tonal contrasts.','这张照片有细腻的明暗层次对比。'),sources=['https://en.wiktionary.org/wiki/tonal']),
E('tonality','英 /təʊˈnæləti/；美 /toʊˈnæləti/','调性；色调或音调的整体性质','一段音乐里的音像围着一个“家”来组织，整体呈现一定的调性感。','英语借自法语 tonalité；现代可联系 tonal + -ity，但历史不是只有英语内部派生这一条。',B+[['法语 tonal → tonalité','音调相关的 → 调性、整体调子'],['英语 tonality','音乐调性；色调或音调特征']],'在音乐里 tonality 常指音和和弦围绕调性中心形成的关系；听到结束时“回家了”的感觉，是一个入门比喻。它也可用于作品整体色调或声音性质，但不能只靠这个比喻推导所有专业定义。','major tonality；minor tonality；a sense of tonality；the tonality of an image。','tone 可以是一种声音特征，tonality 常看整套关系或整体性质；tempo 则是速度，完全是另一个维度。',('The piece gradually shifts from a major to a minor tonality.','这首作品逐渐从大调调性转向小调调性。'),('The warm tonality of the image suits the quiet scene.','画面的暖色调很适合这个安静的场景。'),sources=['https://en.wiktionary.org/wiki/tonality']),
E('ringtone','英 /ˈrɪŋtəʊn/；美 /ˈrɪŋtoʊn/','电话来电铃声','电话用一小段声音提醒你：有人在找你。','ring“铃声、响铃”+ tone“声音”，现代英语合成词；ring 与 tone 两个成分分别提供提醒和声音含义。',[['英语 ring“响铃” + tone“声音”','两个成分并列组合'],['英语 ringtone','电话来电提示音']],'ringtone 可以是传统铃声、音乐片段或其他声音，不需要真的有一只铃铛。把某首歌 set as your ringtone 就是设置成来电铃声；一般的消息提示音更常说 notification sound。','change the ringtone；a default ringtone；set as a ringtone。','ringtone 多用于电话来电；alarm tone 通常是闹钟或警报声。具体设备可能自定名称，学习时先分清场景。',('Her phone has a very distinctive ringtone.','她的手机铃声很有辨识度。'),('I changed the ringtone to something quieter.','我把来电铃声换成了更轻柔的声音。'),sources=['https://en.wiktionary.org/wiki/ringtone'])]
